import os,sys,base64,io,tarfile,subprocess
from pathlib import Path
os.environ['CUDA_VISIBLE_DEVICES']=''
os.environ['PJRT_DEVICE']='TPU'
root=Path('/kaggle/working/code');root.mkdir(exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(''))) as archive:
    archive.extractall(root)
subprocess.check_call([sys.executable,'-m','pip','install','-q','transformers==4.57.6','pycocotools','scipy'])
os.environ['PYTHONPATH']=str(root)
subprocess.run([sys.executable,'-u',str(root/'train.py')]+['--probe-steps', '4', '--seconds', '5100', '--bf16', '--checkpoint-activations'],cwd=root,check=True,timeout=5280)
